class LRUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.head, self.tail = None, None

    def _add_node(self, key, value):
        node = Node(key, value)
        self.cache[key] = node
        if not self.head:
            self.head, self.tail = node, node
        else:
            self.tail.next, node.pre = node, self.tail
            self.head.pre, self.tail = self.head, node

    def _remove_node(self, key):
        if not self.cache.get(key):
            return
        node = self.cache[key]
        prev, nxt = node.pre, node.next
        if not prev:
            self.head = nxt
        else:
            prev.next, nxt.pre = nxt, prev
        if not nxt:
            self.tail = prev

    def get(self, key):
        node = self.cache.get(key)
        if not node:
            return -1
        self._remove_node(node)
        self._add_node(key, node.value)
        return node.value

    def put(self, key, value):
        if self.capacity == 0:
            return
        node = self.cache.get(key)
        if not node:
            if len(self.cache) >= self.capacity:
                self._remove_node(self.head)
            node = Node(key, value)
            self.cache[key] = node
            if not self.head:
                self.head, self.tail = node, node
        else:
            node.value = value
            self._move_to_head(node)
        return

    def _move_node(self, node):
        if not self.head:
            return
        if node.pre:
            node.pre.next, node.next = node.next, node.pre
        else:
            self.head = node.next

    def _add_node_to_head(self, node):
        if not self.head:
            self.head, self.tail = node, node
        else:
            node.next, self.head.pre = self.head, node
            self.head = node

    def _remove_node_from_head(self):
        if not self.head:
            return
        node = self.head
        self.head = node.next
        if not self.head:
            self.tail = None
        else:
            self.head.pre = None

    def _move_to_head(self, node):
        if not self.head:
            return
        if node.pre:
            node.pre.next, node.next = node.next, node.pre
        else:
            self.head, self.tail = node, node

    class Node:
        def __init__(self, key, value):
            self.key = key
            self.value = value
            self.pre = None
            self.next = None

