def merge_dicts(a, b):
    for key in b:
        if key in a and hasattr(a[key], '__dict__') and hasattr(b[key], '__dict__'):
            if not isinstance(a, dict):
                a = {k: v for k, v in a.items() + [(k, v) for k, v in b[key]]}
            else:
                a = {**a, **b}
