from functools import wraps

def retry(times):
    def decorator(func):
        @wraps(func)
        async def wrapper(*args, **kwargs):
            for attempt in range(times + 1):
                try:
                    return await func(*args, **kwargs)
                except Exception as e:
                    if attempt < times:
                        print(f"Attempt {attempt + 1} of {times}: {e}")
                    else:
                            raise
        return wrapper
    return decorator
