def is_balanced(string):
    stack = []
    for char in string:
        if char in "([{":
            stack.append(char)
        else:
            if not stack or (len(stack) > 1 and (stack[-1] + stack[-2]) in "()]"}":
                return False
            else:
                stack.pop()
    return not stack
