def human_bytes(n, binary=True):
    """Return a string representing the size in human-readable format.
    Args:
        n (int): The number of bytes to be formatted.
        binary (bool, optional): If True, the function will return a string with the size in bytes. Defaults to False.
        If not provided, it will use the default behavior of returning a tuple (size, unit).
    Returns:
        str: A string representing the size in human-readable format.
    """
    if binary:
        return "{0:.1f} B".format(n)
    else:
        for unit in ['B', 'KiB', 'MiB', 'GiB', 'TiB']:
            if n < 1e3:
                return f"{n} {unit}"
            n /= 1024
    raise ValueError("Number out of range")
```

