def parse_duration(interval):
    pattern = r'(\d+)(\w+)'
    m = compile(pattern)
    match = m.match(interval)

    if not match:
        raise ValueError("Invalid time format. Please use the format 'hh:mm' or 'hhmms' or 'dd'")

    time_str, unit = match.groups()
    if unit.upper() == 'H' and len(time_str) != 2:
        raise ValueError("Invalid time format. Please use 'hh:mm' or 'hhmm's or 'dd'")
    elif unit.upper() == 'H':
        return int(time_str) * 60 * 60
    else:
        return int(round(float(time_str) * 60), 0)

