from collections import deque

def sliding_window(it, n=1):
    it = iter(it)
    window = deque()

    for _ in range(n - 1):
        window.append(next(it, None))
    for elem in it:
        if not window:
            yield next(window)
            window.clear()
        window.append(elem)
    for _ in range(n - 1, 0, -1):
        window.popleft()
        if not window:
            yield next(it, None)
            return
        window.append(next(it, None))
    if not window:
        while True:
            try:
                yield next(it, None)
            except StopIteration:
                break
    else:
        while window:
            yield next(window, None)
```

This code defines a generator function `sliding_window` that takes an iterable and an optional integer `n`, which is the window size. It uses a deque to keep track of the last `n-1` elements and an additional element from the end. It then iterates through the input iterable, updating the window and yielding the last `n-1\) elements of the window.

