def levenshtein(a, b):
    if len(a) < len(b): a, b = b, a
    c = [i for i in range(len(a) + 1)]
    for i in range(1, len(b) + 1):
        c[i] = [i]
        for j in range(1, len(a) + 1):
            c[i].append(min(c[i - 1][j - 1] + (a[j - 1] != b[i - 1]), c[i - 1][j] + 1, c[i - 1][j - 1] + (a[j - 1] != b[i - 1] or a[j - 1] == b[i - 1] and c[i - 1][j - 1] + (a[j - 1] != b[i - 1]))))
    return c[-1]
