def coin_change(coins, amount, memo=None):
    if memo is None:
        memo = {}
    if amount in memo:
        return memo[amount]
    if amount == 0:
        return 0
    min_coins = float('inf')
    for coin in coins:
        if amount - coin >= 0:
            num_coins = 1 + coin_change(coins, amount - coin, memo)
            if num_coins < min_coins:
                min_coins = num_coins
    memo[amount] = -min_coins if min_coins == float('inf') else -min_coin
    return -memo[amount]

