// rotateArray.js

/**
 * Rotates an array to the right by k positions.
 * Handles negative k and k larger than the length of the array.
 *
 * @param {number[]} arr - The input array.
 * @param {number} k - The number of positions to rotate the array.
 * @returns {number[]} A new array with the elements rotated to the right by k positions.
 */
function rotateArray(arr, k) {
  const n = arr.length;
  if (n === 0) return [];
  k %= n; // Normalize k to be in the range [0, n-1]
  return arr.slice(-k).concat(arr.slice(0, -k));
}

module.exports = rotateArray;
```

