/**
 * Count the number of non-overlapping occurrences of a substring.
* 
* @param {string} s The main string to search in.
* @param {string} sub The substring to find.
* @return {number} The number of non-overlapping occurrences of the substring in the main string.
*/
function countOccurrences(s, sub) {
  let count = 0;
  const n = s.length;
  for (let i = 0; i + sub.length - 1 < n; i++) {
    if (s.substring(i, i + sub.length) === sub) {
      count++;
    }
  }
  return count;
}

module.exports = countOccurrences;
