type Handler = (e: { type: string }) => void;

class Emitter {
  private eventListeners: Record<string, (event: { type: string }) => void> = {};

  on<T>(type: keyof Emitter, listener: (event: { type: string }) => void) {
    if (!this.eventListeners[type]) {
      this.eventListeners[type] = [];
    }
    this.eventListeners[type].push(listener);
  }

  emit<T = any>(event: { type: keyof Emitter['eventListeners'] }["type"], ...args: any[]) {
    const eventListeners = this.eventListeners[event] || [];
    for (const listener of eventListeners) {
      try {
        if (typeof listener === 'function') {
          listener(...args);
        }
      } catch (error) {
        console.error(`Failed to call event listener for type "${event}":`, error);
      }
    }
  }
}

export default Emitter;
```

### Explanation:
1. **Type Definition**:
   - `type Handler = (e: { type: string }) => void;`
  - This defines a type `Handler` that takes an object with a single property `type` of type string and returns `void`.

2. **Emitter Class**:
  - The `Emitter` class manages a map of event types and their corresponding event listeners.
  - The `on` method is used to register a new event listener for a specific type.
  - The `emit` method triggers all registered listeners for the specified event type.

3. **TypeScript Type Definitions**:
  - The `Emitter` class is defined with the necessary type definitions for the event system.

### Usage:
```typescript
// Example usage
const emitter = new Emitter();

// Register a listener for the 'myEvent' type
emitter.on('myEvent', (event: { type: string }) => {
  console.log(`Received event of type: ${event.type}`);
});

// Emit the event
emitter.emit('myEvent', 'Hello, world!');
```

