export interface Cache<K, V> {
  get(key: K): V | undefined;
  set(key: K, value: V, ttl?: number): void;
}

class MapCache<K, V> implements Cache<K, V> {
  private cache: { [key: string]: { value: any; ttl: number | null } };

  constructor() {
    this.cache = {};
  }

  get(key: K): V | undefined {
    const entry = this.cache[key];
    if (entry) {
      if (Date.now() < (entry.ttl || 0)) {
        return entry.value;
      } else {
        this.cache[key] = { value: null, ttl: 0 };
      }
    }
    return undefined;
  }

  set(key: K, value: V, ttl?: number): void {
    if (this.cache[key]) {
      this.cache[key] = { value, ttl: ttl || 0 };
    } else {
      this.cache[key] = { value, ttl: ttl || 0 };
    }
  }
}
```

