First, make sure you have the necessary packages installed. You can install Flask using pip if you haven't already:

```bash
pip install Flask
```

Now, create a new Python file, for example, `app.py`, and add the following code:

```python
from flask import Flask, request, jsonify

app = Flask(__name__)

# Sample data
orders = {
    1: {"id": 1, "customer_name": "John Doe", "status": "pending"},
    2 => {"id": 2, "customer_name": "Jane Smith", "status": "completed"}
}

# Helper function to get an order by ID
def get_order(order_id):
    return next((order for order in orders.values() if order.get("id") == str(order_id) else None), None)

# GET /orders/{order_id}
@app.route(f"/orders/<int:order_id>", methods=["GET"])
def get_order_by_id(order_id):
    order = get_order(order_id)
    if order:
        return jsonify({"order": order}), 200
    else:
        return "Order not found", 404

# GET /orders - Get all orders
@app.route("/orders/", methods=["GET"])
def get_orders():
    return jsonify(list(orders.values())), 200)

# POST /orders - Create a new order
@app.route("/orders/", methods=["POST"])
def create_order():
    data = request.get_json()
    order_id = len(orders) + 1
    new_order = {
        "id": order_id,
        "customer_name": data.get("customer_name"),
        "status": "pending"
    }
    orders[order_id] = new_order
    return jsonify({"message": "Order created successfully"}), 201

# PUT /orders/<int:order_id> - Update an order
@app.route(f"orders/<int:order_id>/update", methods=["PUT"])
def update_order(order_id):
    order = get_order(order_id)
    if not order:
        return "Order not found", 404
    data = request.get_json()
    if "status" in data:
        order["status"] = data["status"]
    return jsonify({"order": order}), 200)

# DELETE /orders/<int:order_id> - Delete an order
@app.route(f"orders/{order_id}", methods=["DELETE"])
def delete_order(order_id):
    if order_id in orders:
        del orders[order_id]
        return "Order deleted", 200
    else:
        return "Order not found", 404

if __name__ == "__main__":
    app.run(debug=True)
```

This code sets up a simple order management system with the following endpoints:

- `GET /orders/` - Returns all orders.
- `POST /orders/` - Create a new order.
- `PUT /orders/<int:order_id>` - Update an existing order.
- `DELETE /orders/<int:order_id>` - Delete an order.

Make sure to run the Flask application using `python app.py` and test the endpoints using a tool like Postman

