    }).then(() => setFetching(false).catch(console.error));
  };

  return (
    <View>
      <FlatList
        data={data}
        renderItem={({ item }) => <Text>{item}</Text>}
        keyExtractor={(_, index) => `item-${index}`}
        onEndReached={onEndReached}
        onEndReachedThreshold={0.5}
      />
    </View>
  );
};

export default InfiniteScroll;
```

